fn shell_game(n: i32, x: i8) -> i8 {
    // n can be large, reduce moves modulo 6 since cycle length is 6
    let m = (n % 6) as u8;
    let mut pos = x;

    for i in 1..=m {
        if i % 2 == 1 {
            // Odd move: swap between 0 and 1
            pos = match pos {
                0 => 1,
                1 => 0,
                2 => 2,
                _ => pos, // Defensive, though pos should be in {0,1,2}
            };
        } else {
            // Even move: swap between 1 and 2
            pos = match pos {
                1 => 2,
                2 => 1,
                0 => 0,
                _ => pos,
            };
        }
    }

    pos
}